def apply_methodical_revision() -> None:
    for lab in LABS:
        number = int(lab["number"])
        lab["previousResults"] = PREVIOUS_RESULTS[number]
        lab["inputMaterials"] = INPUT_MATERIALS[number]
        lab["sequenceOutput"] = SEQUENCE_OUTPUTS[number]
        lab["taskSteps"] = TASK_STEPS[number]
        lab["workedExample"] = WORKED_EXAMPLES[number]
        lab["optionalTask"] = OPTIONAL_TASKS[number]
        lab["sourceReferences"] = SOURCE_REFERENCES[number]
        lab["selfCheck"] = SELF_CHECKS[number]
        lab["reportSections"] = REPORT_SECTIONS
        lab.pop("sequenceInput", None)
        lab.pop("task", None)
        lab.pop("stages", None)

